CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','user')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.create_dj_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,phone) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'name',new.raw_user_meta_data->>'full_name',''),60),left(coalesce(new.raw_user_meta_data->>'phone',''),20)); RETURN new; END $$;
CREATE TRIGGER dj_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_dj_profile();
CREATE TABLE public.pro_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code_hash text NOT NULL UNIQUE, target_user_id uuid NOT NULL REFERENCES public.profiles(id), device_id text NOT NULL, months integer NOT NULL CHECK(months IN (1,2,3,4,5,6,7,12)), issued_by uuid NOT NULL, issued_at timestamptz NOT NULL DEFAULT now(), redeemed_at timestamptz);
GRANT ALL ON public.pro_codes TO service_role;
ALTER TABLE public.pro_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pro_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), device_id text NOT NULL, expires_at timestamptz NOT NULL, UNIQUE(user_id,device_id));
GRANT SELECT ON public.pro_devices TO authenticated;
GRANT ALL ON public.pro_devices TO service_role;
ALTER TABLE public.pro_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_pro_devices ON public.pro_devices FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.issue_pro_code(_user_id uuid,_device text,_months integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE c text; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _months NOT IN (1,2,3,4,5,6,7,12) OR _device !~ '^[A-F0-9]{8}$' THEN RAISE EXCEPTION 'Invalid duration or device'; END IF; c := 'PRO-' || upper(encode(gen_random_bytes(16),'hex')); INSERT INTO public.pro_codes(code_hash,target_user_id,device_id,months,issued_by) VALUES(encode(digest(c,'sha256'),'hex'),_user_id,_device,_months,auth.uid()); RETURN c; END $$;
REVOKE ALL ON FUNCTION public.issue_pro_code(uuid,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.issue_pro_code(uuid,text,integer) TO authenticated;
CREATE FUNCTION public.redeem_pro_code(_code text,_device text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE c public.pro_codes; expiry timestamptz; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT * INTO c FROM public.pro_codes WHERE code_hash=encode(digest(upper(trim(_code)),'sha256'),'hex') FOR UPDATE; IF NOT FOUND OR c.target_user_id<>auth.uid() OR c.device_id<>_device OR c.redeemed_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid or already used code'; END IF; IF NOT EXISTS(SELECT 1 FROM public.pro_devices WHERE user_id=auth.uid() AND device_id=_device) AND (SELECT count(*) FROM public.pro_devices WHERE user_id=auth.uid() AND expires_at>now())>=2 THEN RAISE EXCEPTION 'Already active on two devices'; END IF; SELECT greatest(now(),expires_at) INTO expiry FROM public.pro_devices WHERE user_id=auth.uid() AND device_id=_device; expiry := coalesce(expiry,now()) + make_interval(months=>c.months); INSERT INTO public.pro_devices(user_id,device_id,expires_at) VALUES(auth.uid(),_device,expiry) ON CONFLICT(user_id,device_id) DO UPDATE SET expires_at=excluded.expires_at; UPDATE public.pro_codes SET redeemed_at=now() WHERE id=c.id; RETURN expiry; END $$;
REVOKE ALL ON FUNCTION public.redeem_pro_code(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_pro_code(text,text) TO authenticated;